# Usage: Step 2c Assign Groups by Polygon <Groups_Reporting_Units_Feature_Class> <Benchmark_Group_or_Reporting_Unit_> <Polygon_Group_Boundary> <Use_Polygon_Attributes> <Benchmark_Group_Field> <Output_Feature_Class>
# Description:
# This tool is the second of three steps in preparing data for the AIM Terrestrial Benchmark Tool. It allows the user to assign benchmark groups or reporting units by selecting points using a known polygon.
#
# Instructions: Input the benchmark group or reporting unit name (e.g., Loamy, Yellow Creek Allotment, etc.) and then navigate to the location of your shapefile or feature class defining the area for your benchmark group or reporting unit. Select OK.

# ---------------------------------------------------------------------------

# Import arcpy module
import arcpy

# Script arguments
Points_Feature_Class = arcpy.GetParameterAsText(0)

Polygon_Group_Boundary = arcpy.GetParameterAsText(1)

Use_Polygon_Attributes = arcpy.GetParameterAsText(2)

Benchmark_Group_or_Reporting_Unit = arcpy.GetParameterAsText(3)

Group_Field = arcpy.GetParameterAsText(4)

Group_Type = arcpy.GetParameterAsText(5)

# we want to just save in the same directory as the point feature class. this should be a gdb.
desc = arcpy.Describe(Points_Feature_Class)
path = desc.path

Output_Name = Points_Feature_Class + "_grouped"

Output_Feature_Class = path + "\\" + Output_Name


if Use_Polygon_Attributes == 'true':

    # first select only the relevant field from the group polygon
    fields = arcpy.FieldMappings()
    fields.addTable(Polygon_Group_Boundary)

    # list of fields to keep from the polygon (defined by input parameter)
    keepers = [Group_Field]

    for field in fields.fields:
        if field.name not in keepers:
            fields.removeFieldMap(fields.findFieldMapIndex(field.name))

    # add in fields from aim points
    fields.addTable(Points_Feature_Class)

    # Process: Spatial Join
    arcpy.SpatialJoin_analysis(Points_Feature_Class, Polygon_Group_Boundary, Output_Feature_Class, "JOIN_ONE_TO_ONE", "KEEP_ALL", fields, "INTERSECT", "", "")

    # Process: Add Field (2)
    arcpy.AddField_management(Output_Feature_Class, "BenchmarkGroup", "TEXT", "","","","Benchmark Group")

    # Basically just renaming to benchmark group
    if Group_Type == 'Benchmark Group':
        fieldlist = ["BenchmarkGroup", Group_Field]
    else:
        fieldlist = ["ReportingUnit", Group_Field]

    with arcpy.da.UpdateCursor(Output_Feature_Class, fieldlist) as curs:
        for row in curs:
            row[0] = row[1]
            curs.updateRow(row)

    # May want to add something here to delete unneeded fields from join


else:

    # Process: Add Field
    arcpy.AddField_management(Points_Feature_Class, "BenchmarkGroup", "TEXT", "", "", "", "", "NULLABLE", "NON_REQUIRED", "")

    # Process: Select Layer By Location
    arcpy.SelectLayerByLocation_management(Points_Feature_Class, "WITHIN", Polygon_Group_Boundary, "", "NEW_SELECTION", "NOT_INVERT")

    # Process: Calculate Field
    arcpy.CalculateField_management(Points_Feature_Class, "BenchmarkGroup", "'" + Benchmark_Group_or_Reporting_Unit + "'")

    # Process: Select Layer By Attribute
    arcpy.SelectLayerByAttribute_management(Points_Feature_Class, "CLEAR_SELECTION", "")

    # Output field calc to output location
    arcpy.FeatureClassToFeatureClass_conversion(Points_Feature_Class, path, Output_Name)

# Adding Outputs to current project
aprx = arcpy.mp.ArcGISProject("CURRENT")
aprxMap = aprx.activeMap
aprxMap.addDataFromPath(Output_Feature_Class)
